    {...common,driver_id:env.get('driver_5_id'),sessions_per_week:{min:5,max:5},weekday_weights:{'0':1,'1':1,'2':1,'3':1,'4':1,'5':1,'6':1},hour_weights:{'6':1,'9':1,'12':1,'15':1,'18':1,'21':1},start_time_jitter_minutes:59}
