const body=insomnia.response.json(); const env=insomnia.baseEnvironment; const drivers=[1,2,3,4,5].map(n => env.get('driver_' + n + '_id')); const matches=body.filter(item => drivers.includes(item.owner_id)); const reservationIds=new Set(JSON.parse(env.get('reservation_results_json') || '[]').map(item => item.id));
insomnia.test('completed Sessions are rooted in accepted Reservations', () => { insomnia.expect(insomnia.response.code).to.eql(200); insomnia.expect(matches.length).to.be.greaterThan(0); insomnia.expect(matches.every(item => typeof item.reservation_id === 'string' && reservationIds.has(item.reservation_id))).to.eql(true); });
if (matches.length) env.set('session_id', matches[0].id);
